    +'.auto-box{width:390px;max-width:92vw;padding:26px;border-radius:24px;color:#fff;text-align:center;background:linear-gradient(135deg,#020617,#0f172a,#1e293b);box-shadow:0 25px 80px rgba(0,0,0,.42)}'
